package main
import("debug/elf";"debug/gosym";"encoding/json";"fmt";"os";"strings";"crypto/sha256";"bytes")
func main(){f,err:=elf.Open(os.Args[1]);if err!=nil{panic(err)};defer f.Close();sec:=f.Section(".gopclntab");if sec==nil{panic("missing Go pclntab")};data,err:=sec.Data();if err!=nil{panic(err)};text:=f.Section(".text");if text==nil{panic("missing text")};tab,err:=gosym.NewTable(nil,gosym.NewLineTable(data,text.Addr));if err!=nil{panic(err)};affected:=[]string{};crypto:=[]string{};for _,fn:=range tab.Funcs{if strings.HasPrefix(fn.Name,"golang.org/x/crypto/openpgp"){affected=append(affected,fn.Name)};if strings.HasPrefix(fn.Name,"golang.org/x/crypto/"){crypto=append(crypto,fn.Name)}};b,err:=os.ReadFile(os.Args[1]);if err!=nil{panic(err)};out:=map[string]interface{}{"binarySHA256":fmt.Sprintf("%x",sha256.Sum256(b)),"functionsExtracted":len(tab.Funcs),"elfSymbolTablePresent":f.Section(".symtab")!=nil,"dwarfDebugInfoPresent":f.Section(".debug_info")!=nil,"rawOpenPGPPathOccurrences":bytes.Count(b,[]byte("golang.org/x/crypto/openpgp")),"affectedOpenPGPFunctions":affected,"otherXCryptoFunctionCount":len(crypto),"otherXCryptoExamples":crypto[:min(10,len(crypto))]};json.NewEncoder(os.Stdout).Encode(out)}
